import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  index,
  pgTable,
  text,
  timestamp,
  unique,
} from 'drizzle-orm/pg-core';

// Admin authentication (US-2.1, guardrail 3). Columns follow Better Auth's core
// schema, which its Drizzle adapter requires, under `admin_*` table names.
// Deliberate deviations from the rest of the schema, set by the framework:
// text ids generated by Better Auth, and cascade foreign keys so removing a user
// removes the user's sessions and account.
//
// Personal data (guardrail 5): the only personal value is the admin's email.
// `name` is the constant 'admin'. A session row holds no IP address and no user
// agent: both columns exist because the adapter expects them, and a check
// constraint keeps them null whatever writes the row.

export const adminUsers = pgTable('admin_users', {
  id: text('id').primaryKey(),
  // Always the constant 'admin' (no personal data).
  name: text('name').notNull(),
  // Stored trimmed and lowercased by src/server/auth/accounts.ts.
  email: text('email').notNull().unique(),
  emailVerified: boolean('email_verified').notNull().default(false),
  image: text('image'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
});

export const adminAccounts = pgTable(
  'admin_accounts',
  {
    id: text('id').primaryKey(),
    // The user id, for the credential provider.
    accountId: text('account_id').notNull(),
    // Always 'credential' in S2.1.
    providerId: text('provider_id').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => adminUsers.id, { onDelete: 'cascade' }),
    // A salted scrypt hash from better-auth/crypto; never the plain password.
    password: text('password'),
    accessToken: text('access_token'),
    refreshToken: text('refresh_token'),
    idToken: text('id_token'),
    accessTokenExpiresAt: timestamp('access_token_expires_at', { withTimezone: true }),
    refreshTokenExpiresAt: timestamp('refresh_token_expires_at', { withTimezone: true }),
    scope: text('scope'),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [unique('admin_accounts_provider_id_user_id_unique').on(table.providerId, table.userId)],
);

export const adminSessions = pgTable(
  'admin_sessions',
  {
    id: text('id').primaryKey(),
    // The opaque session token; the cookie carries it signed.
    token: text('token').notNull().unique(),
    userId: text('user_id')
      .notNull()
      .references(() => adminUsers.id, { onDelete: 'cascade' }),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    // Never filled (guardrail 5): the check below refuses any value.
    ipAddress: text('ip_address'),
    userAgent: text('user_agent'),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index('admin_sessions_user_id_idx').on(table.userId),
    check(
      'admin_sessions_no_ip_or_user_agent',
      sql`${table.ipAddress} is null and ${table.userAgent} is null`,
    ),
  ],
);

// Required by the framework, unused in S2.1 (no email verification, no reset).
export const adminVerifications = pgTable('admin_verifications', {
  id: text('id').primaryKey(),
  identifier: text('identifier').notNull(),
  value: text('value').notNull(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
});
